  graph = mountCodeMap($('.s-factory-host'), a, { sample:state.snapshot.repository.fullName==='illustrative/document-workspace', onSource: openFile, onContext(path, focus) { state.packetPaths.add(path); if (focus) state.packetFocus[path] = focus; else delete state.packetFocus[path]; state.page = 'context'; render(); } });
  if(state.mapSelection && (a.byId.has(state.mapSelection) || a.operations.some(op=>op.id===state.mapSelection)))graph.focus(state.mapSelection);
  graph.setTasks(factoryFor(state.snapshot, scopedFiles().map(f => f.path), state.activity).D.workOrders);
  graph.setLens(state.lens);
